import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Create sprite plane based on atlas region aspect ratio (512x320)
  const aspectRatio = 512 / 320;
  const height = 0.5;
  const width = height * aspectRatio;

  const geometry = new THREE.PlaneGeometry(width, height);

  // Load and apply ceramic grain texture
  const textureAsset = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');

  // Create TSL-based material with texture node
  const textureNode = texture(textureAsset);
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: textureNode
  });

  const spriteMesh = new THREE.Mesh(geometry, material);
  group.add(spriteMesh);

  // Render text content via font atlas
  if (config.textContent && ctx.fontAtlas) {
    const textStr = typeof config.textContent === 'string'
      ? config.textContent
      : (Array.isArray(config.textContent) ? config.textContent[0] : null);

    if (textStr) {
      const textMesh = ctx.fontAtlas.create(textStr, {
        font: 'Lora',
        size: 0.34,
        weight: 400,
        color: '#16161d',
        align: 'center'
      });

      if (textMesh) {
        textMesh.position.z = 0.01;
        group.add(textMesh);
      }
    }
  }

  // Apply scene placement
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Setup event handlers and cleanup
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureAsset.dispose();
  };

  return group;
}
